tasks.answer:
graph = {'나': ['지아', '민수'], '지아': ['나', '하준'], '민수': ['나', '하준', '서연'],
         '하준': ['지아', '민수', '도윤'], '서연': ['민수'], '도윤': ['하준', '예준'], '예준': ['도윤']}

def steps(start):
    dist = {start: 0}
    queue = [start]
    while queue:
        cur = queue.pop(0)
        for nxt in graph[cur]:
            if nxt not in dist:
                dist[nxt] = dist[cur] + 1
                queue.append(nxt)
    return dist

for name, d in steps('나').items():
    print(f'{name}: {d}단계')
